"""Prepare Loon script adapters without changing native request/body objects.

Configuration conversion is supplied by the caller. Only completion contracts
are adapted here; upstream JavaScript is retained verbatim and never executed
during synchronization.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path, PurePosixPath
import re
import subprocess
from urllib.parse import urlsplit

from _common import write_if_changed
from module_convert import module_targets, parse_module
from qx_compat import can_use_upstream, _tokens
from qx_convert import is_qx_module


OWNERS_FILE = ".github/scripts/loon-scripts-owned.json"
GENERATED_HEADER = "// Generated by .github/scripts/loon_scripts.py; do not edit."
SCRIPT_DIRECTORY = "Surge/Module/Scripts"
RAW_SCRIPT_BASE = "https://raw.githubusercontent.com/HotKids/Rules/refs/heads/master/" + SCRIPT_DIRECTORY + "/"
_OWNED_NAME = re.compile(r"Surge/Module/Scripts/[a-z0-9][a-z0-9._-]*\.js")
_GLOBALS = {"$request", "$response", "$done", "$argument", "$environment", "$script",
            "$persistentStore", "$notification", "$httpClient", "$utils"}
_WEB_APIS = {"TextDecoder", "TextEncoder", "URL", "URLSearchParams", "atob", "btoa"}
_DYNAMIC_GLOBALS = {"eval", "Function", "globalThis", "global", "window", "self", "this", "constructor"}


def _digest(value):
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def _safe_path(root, relative):
    path = root / relative
    if path.is_symlink() or not path.resolve().is_relative_to(root.resolve()):
        raise ValueError("Unsafe Loon generated-script path")
    return path


def _read_owners(root, relative=OWNERS_FILE):
    path = _safe_path(root, relative)
    if not path.exists():
        return {}
    state = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(state, dict) or state.get("version") != 1 or not isinstance(state.get("files"), dict):
        raise ValueError("Invalid Loon script ownership record")
    files = state["files"]
    if any(not isinstance(name, str) or not _OWNED_NAME.fullmatch(name)
           or not isinstance(digest, str) or not re.fullmatch(r"[0-9a-f]{64}", digest)
           for name, digest in files.items()):
        raise ValueError("Invalid Loon script ownership path or fingerprint")
    return dict(files)


def _owned_content(path, digest):
    if not path.is_file():
        return False
    content = path.read_bytes()
    return hashlib.sha256(content).hexdigest() == digest and content.startswith((GENERATED_HEADER + "\n").encode())


def _validate_script(content, identifier):
    try:
        result = subprocess.run(["node", "--check"], input=content, text=True,
                                capture_output=True, timeout=30)
    except (OSError, subprocess.TimeoutExpired):
        raise RuntimeError("Loon script validation requires a working Node.js parser") from None
    if result.returncode:
        raise ValueError(f"Loon script syntax validation failed: {identifier}")


def _script_features(source, identifier):
    tokens = _tokens(source)
    if tokens is None:
        raise ValueError(f"Cannot determine Loon script host APIs: {identifier}")
    webview = False
    for index, (kind, value) in enumerate(tokens):
        if kind != "identifier":
            continue
        previous = tokens[index - 1][1] if index else None
        if value in _DYNAMIC_GLOBALS:
            raise ValueError(f"Unsupported dynamic Loon script access: {identifier}")
        if value.startswith("$") and len(value) > 1:
            if value not in _GLOBALS or previous in {".", "?."}:
                raise ValueError(f"Unsupported Loon script host API: {identifier}")
        if value in _WEB_APIS and previous not in {".", "?."}:
            webview = True
    return webview


def _option_spans(value):
    """Locate native option keys outside quoted or grouped option values."""
    matches, stack, quote, escaped = [], [], None, False
    pairs = {"(": ")", "[": "]", "{": "}"}
    key = re.compile(r"(?:^|,)\s*([a-z][a-z0-9-]*)\s*=")
    for index, char in enumerate(value):
        if escaped:
            escaped = False
            continue
        if char == "\\":
            escaped = True
            continue
        if quote:
            if char == quote:
                quote = None
            continue
        if char in "\"'":
            quote = char
        elif char in pairs:
            stack.append(pairs[char])
        elif stack and char == stack[-1]:
            stack.pop()
        elif not stack and (index == 0 or char == ","):
            match = key.match(value, index)
            if match:
                matches.append(match)
    return matches


def parse_script_options(value):
    matches, result = _option_spans(value), {}
    for index, match in enumerate(matches):
        end = matches[index + 1].start() if index + 1 < len(matches) else len(value)
        field = value[match.end():end].strip()
        if len(field) > 1 and field[0] in "\"'" and field[-1] == field[0]:
            field = field[1:-1]
        result[match[1]] = field
    return result


def _replace_option(value, key, replacement):
    matches = _option_spans(value)
    for index, match in enumerate(matches):
        if match[1] != key:
            continue
        start = match.end()
        end = matches[index + 1].start() if index + 1 < len(matches) else len(value)
        old = value[start:end]
        leading = old[:len(old) - len(old.lstrip())]
        trailing = old[len(old.rstrip()):]
        stripped = old.strip()
        quote = stripped[0] if len(stripped) > 1 and stripped[0] in "\"'" and stripped[-1] == stripped[0] else ""
        return value[:start] + leading + quote + replacement + quote + trailing + value[end:]
    return value.rstrip() + ", " + key + "=" + replacement


def _rewrite_source(text, routes, direct, webview, bundle_url):
    result, section, cursor = [], None, 0
    for raw in text.splitlines(keepends=True):
        body = raw.rstrip("\r\n")
        ending = raw[len(body):]
        stripped = body.strip()
        if re.fullmatch(r"\[[^]\n]+\]", stripped):
            section = stripped[1:-1]
        if section == "Script" and stripped and not stripped.startswith(("#", "//")) and "=" in stripped:
            route = routes[cursor]
            cursor += 1
            value = stripped.split("=", 1)[1].strip()
            value = _replace_option(value, "script-path", route["url"] if route["url"] in direct else bundle_url)
            if route["url"] in webview:
                engine = parse_script_options(value).get("engine", "auto").lower()
                if engine not in {"auto", "webview"}:
                    raise ValueError("Loon WebAPI script conflicts with its explicit script engine")
                value = _replace_option(value, "engine", "webview")
            indent = body[:len(body) - len(body.lstrip())]
            body = indent + route["name"] + " = " + value
        result.append(body + ending)
    if cursor != len(routes):
        raise ValueError("Converted Loon script routes changed during preparation")
    return "".join(result)


def _bundle_script(routes, bodies, runtime):
    urls = list(dict.fromkeys(route["url"] for route in routes))
    sources = ["function ($done) {\nreturn (function () {\n// BEGIN UPSTREAM SOURCE\n" + bodies[url]
               + "\n// END UPSTREAM SOURCE\n}).call(this);\n}" for url in urls]
    table = [{"name": route["name"], "type": route["type"], "pattern": route.get("pattern"),
              "mode": route["mode"], "source": urls.index(route["url"])} for route in routes]
    return (GENERATED_HEADER + "\n(function (native) {\n" + runtime.rstrip() + "\n"
            + "const sources = [\n" + ",\n".join(sources) + "\n];\n"
            + "const routes = " + json.dumps(table, ensure_ascii=False) + ";\n"
            + """const label = native.script && native.script.name;
let matches = typeof label === 'string' ? routes.filter(route => route.name === label) : [];
if (matches.length === 0) {
  const declared = native.script && native.script.type;
  const stage = ['http-request', 'http-response', 'cron'].includes(declared) ? declared
    : native.response ? 'http-response' : native.request ? 'http-request' : 'cron';
  const url = native.request && native.request.url;
  matches = routes.filter(route => {
    if (stage === 'cron' || route.type !== stage || typeof url !== 'string') return false;
    try {
      const insensitive = route.pattern.startsWith('(?i)');
      const pattern = insensitive ? route.pattern.slice(4) : route.pattern;
      return new RegExp(pattern, insensitive ? 'i' : '').test(url);
    } catch (_) { return false; }
  });
  matches = matches.filter((route, index, all) => all.findIndex(other =>
    other.source === route.source && other.mode === route.mode) === index);
}
if (matches.length !== 1) return native.done({});
const route = matches[0];
return sources[route.source].call(this, createLoonDone(native.done, route.mode));
})({
request: typeof $request === 'undefined' ? undefined : $request,
response: typeof $response === 'undefined' ? undefined : $response,
script: typeof $script === 'undefined' ? undefined : $script,
done: typeof $done === 'undefined' ? undefined : $done
});
""")


class PreparedLoonScripts:
    def __init__(self, root, entries, originals, converted_sources, converted_by_target, scripts, owners):
        self.root = root.resolve()
        self.entries = json.dumps(entries, sort_keys=True)
        self.originals = {url: _digest(body) for url, body in originals.items()}
        self._converted_inputs = {url: _digest(body) for url, body in converted_sources.items()}
        self.converted_by_target = converted_by_target
        self.sources = dict(converted_sources)
        for (_target, url), text in converted_by_target.items():
            # The first format supplies native labels to QX's conflict checks.
            if self.sources[url] == converted_sources[url]:
                self.sources[url] = text
        self.scripts, self.owners = scripts, owners

    def source_text(self, url, target, fallback):
        return self.converted_by_target.get((target, url), fallback)

    def validate_inputs(self, root, entries, prefetched, converted_prefetched=None):
        originals = {entry["url"]: prefetched.get(entry["url"]) or "" for entry in entries}
        if (Path(root).resolve() != self.root or json.dumps(entries, sort_keys=True) != self.entries
                or {url: _digest(body) for url, body in originals.items()} != self.originals):
            raise ValueError("Prepared Loon script batch does not match module sources")
        if converted_prefetched is not None:
            native = {entry["url"]: converted_prefetched.get(entry["url"]) or "" for entry in entries}
            if {url: _digest(body) for url, body in native.items()} != self._converted_inputs:
                raise ValueError("Prepared Loon script batch does not match converted sources")

    def validate_destinations(self):
        qx_owned = _read_owners(self.root, ".github/scripts/qx-scripts-owned.json")
        for relative in self.owners:
            _safe_path(self.root, relative)
        for relative, content in self.scripts.items():
            if relative in qx_owned:
                raise ValueError("Loon and QX generated-script basenames collide")
            path = _safe_path(self.root, relative)
            if path.exists() and path.read_bytes() != content.encode("utf-8"):
                if relative not in self.owners or not _owned_content(path, self.owners[relative]):
                    raise ValueError(f"Generated Loon script has local edits; refusing to overwrite: {relative}")

    def write_scripts(self):
        self.validate_destinations()
        for relative, content in self.scripts.items():
            write_if_changed(_safe_path(self.root, relative), content)

    def finish(self):
        for relative, digest in self.owners.items():
            if relative in self.scripts:
                continue
            path = _safe_path(self.root, relative)
            if path.exists() and _owned_content(path, digest):
                path.unlink()
            elif path.exists():
                print(f"  [WARN] {relative} 已手动修改，保留并解除 Loon 自动清理归属")
        if self.scripts or self.owners or (self.root / OWNERS_FILE).exists():
            state = {"version": 1, "files": {name: _digest(body) for name, body in sorted(self.scripts.items())}}
            write_if_changed(_safe_path(self.root, OWNERS_FILE), json.dumps(state, ensure_ascii=False, indent=2) + "\n")


def prepare_loon_scripts(entries, original_prefetched, converted_prefetched, root, download_scripts):
    root = Path(root)
    originals = {entry["url"]: original_prefetched.get(entry["url"]) or "" for entry in entries}
    native = {entry["url"]: converted_prefetched.get(entry["url"]) or "" for entry in entries}
    loon = {url for url in originals if urlsplit(url).path.lower().endswith((".plugin", ".lpx"))
            or originals[url] != native[url]}
    groups = {}
    if loon:
        for entry in entries:
            for target in module_targets(entry["name"]):
                groups.setdefault(target, []).append(entry)
    plans, references = {}, []
    for target, members in groups.items():
        if not any(entry["url"] in loon for entry in members):
            continue
        first = members[0]
        title = next((m[1].strip() for line in native[first["url"]].splitlines()
                      if (m := re.match(r"\s*#!\s*name\s*=(.*)", line))), "Loon")
        title = first.get("overrides", {}).get("name", title)
        source_routes, routes, native_labels, seen = {}, [], set(), set()
        for entry in members:
            url = entry["url"]
            if url in seen:
                continue
            seen.add(url)
            if url not in loon:
                if urlsplit(url).path.lower().endswith(".snippet") or is_qx_module(native[url]):
                    continue
                _, sections = parse_module(native[url])
                native_labels.update(line.split("=", 1)[0].strip() for line in sections.get("Script", [])
                                     if "=" in line and not line.lstrip().startswith(("#", "//")))
                continue
            _, sections = parse_module(native[url])
            current = []
            for line in sections.get("Script", []):
                if not line.strip() or line.lstrip().startswith(("#", "//")):
                    continue
                if "=" not in line:
                    raise ValueError("Converted Loon script is not a native script assignment")
                options = parse_script_options(line.split("=", 1)[1])
                script_type, script_url = options.get("type"), options.get("script-path")
                if script_type not in {"http-request", "http-response", "cron"} or not script_url:
                    raise ValueError("Unsupported converted Loon script execution mode")
                parsed = urlsplit(script_url)
                if parsed.scheme not in {"http", "https"} or not parsed.hostname or parsed.username or parsed.password:
                    raise ValueError("Loon script path must be an HTTP URL without user information")
                if script_type != "cron" and not options.get("pattern"):
                    raise ValueError("Converted Loon HTTP script requires a pattern")
                mode = "cron" if script_type == "cron" else script_type[5:]
                if mode != "cron" and options.get("requires-body", "false").lower() in {"true", "1"}:
                    mode += "-body"
                route = {"name": f"{title}_{len(routes) + 1}", "type": script_type,
                         "pattern": options.get("pattern"), "mode": mode, "url": script_url}
                routes.append(route)
                current.append(route)
                references.append(script_url)
            source_routes[url] = current
        if native_labels.intersection(route["name"] for route in routes):
            raise ValueError("Loon script labels collide with native scripts in the same module")
        plans[target] = source_routes, routes
    bodies, direct, webview = {}, set(), set()
    if references:
        urls = list(dict.fromkeys(references))
        bodies = download_scripts(urls)
        for url in urls:
            body, identifier = bodies.get(url), "source-" + _digest(url)[:12]
            if not isinstance(body, str) or not body.strip() or "\0" in body:
                raise ValueError(f"Loon script download is empty or invalid: {identifier}")
            if re.match(r"\s*(?:<!doctype\s+html|<html\b)", body, re.I):
                raise ValueError(f"Loon script download returned HTML: {identifier}")
            _validate_script("(function () {\n" + body + "\n});\n", identifier)
            if _script_features(body, identifier):
                webview.add(url)
            modes = {r["mode"] for _, routes in plans.values() for r in routes if r["url"] == url}
            if all(can_use_upstream(body, mode) for mode in modes):
                direct.add(url)
    converted, scripts, identities = {}, {}, {}
    runtime = None
    for target, (source_routes, routes) in plans.items():
        adapted = [route for route in routes if route["url"] not in direct]
        bundle_url = None
        if adapted:
            identity = PurePosixPath(target).with_suffix("").as_posix()
            basename = PurePosixPath(identity).name.lower() + ".js"
            relative = SCRIPT_DIRECTORY + "/" + basename
            if not _OWNED_NAME.fullmatch(relative):
                raise ValueError("Loon bundle requires a lowercase ASCII module basename")
            if relative in identities and identities[relative] != identity:
                raise ValueError("Loon module basenames collide after lowercasing")
            identities[relative] = identity
            if runtime is None:
                runtime = Path(__file__).with_name("loon-runtime.js").read_text(encoding="utf-8")
            body = _bundle_script(adapted, bodies, runtime)
            if relative in scripts and scripts[relative] != body:
                raise ValueError("Loon module formats require conflicting bundles with the same basename")
            _validate_script(body, basename)
            scripts[relative] = body
            bundle_url = RAW_SCRIPT_BASE + basename
        for url, current in source_routes.items():
            converted[(target, url)] = _rewrite_source(native[url], current, direct, webview, bundle_url)
    batch = PreparedLoonScripts(root, entries, originals, native, converted, scripts, _read_owners(root))
    batch.validate_destinations()
    return batch
